// Single source of truth for selection. Reads url_candidates rows, applies the v0.1
// approval gate, prioritizes, hard-caps at 5, and annotates every row (_selected / _skip_reason).
const rows = $input.all().map(i => i.json).filter(Boolean);
function pad(n){ return String(n).padStart(2, '0'); }
const d = new Date();
const now = d.toISOString();
const stamp = d.getFullYear()+pad(d.getMonth()+1)+pad(d.getDate())+'_'+pad(d.getHours())+pad(d.getMinutes())+pad(d.getSeconds());
const run_id = 'approved_run_' + stamp;
const MAX = 5; // HARD CAP: max 5 approved URLs per run

function str(v){ return (v==null?'':String(v)).trim(); }
function lc(v){ return str(v).toLowerCase(); }

// Aggregators/directories/marketplaces/socials/media require an explicit operator override
// (add 'aggregator_approved' to the candidate notes). Direct competitors flow through normally.
const BLOCKED_TYPES = ['aggregator','directory','marketplace','social','media_article'];

const evaluated = [];
for (const r of rows){
  const approval = lc(r.approval_status);
  const dedup = lc(r.dedup_status);
  const registry = lc(r.registry_status);
  const url = str(r.candidate_url);
  const ctype = lc(r.candidate_type);
  const notesLc = lc(r.notes);
  const overrideAggregator = notesLc.includes('aggregator_approved') || notesLc.includes('approved_aggregator');

  let eligible = true; let skip_reason = '';
  if (approval !== 'approved'){ eligible=false; skip_reason='approval_status=' + (approval||'empty') + ' (need approved)'; }
  else if (dedup !== 'unique'){ eligible=false; skip_reason='dedup_status=' + (dedup||'empty') + ' (need unique)'; }
  else if (registry !== 'not_in_registry'){ eligible=false; skip_reason='registry_status=' + (registry||'empty') + ' (need not_in_registry)'; }
  else if (url === ''){ eligible=false; skip_reason='candidate_url empty'; }
  else if (BLOCKED_TYPES.includes(ctype) && !overrideAggregator){ eligible=false; skip_reason='candidate_type=' + ctype + ' needs explicit operator approval (add aggregator_approved to notes)'; }

  evaluated.push({ row:r, eligible, skip_reason, ctype, url,
    confidence: parseInt(r.confidence_score)||0,
    rank: parseInt(r.rank)||999 });
}

// Prioritize eligible: direct_competitor first, higher confidence, lower rank.
const eligibleList = evaluated.filter(e => e.eligible);
eligibleList.sort((a,b)=>{
  const ad = a.ctype==='direct_competitor'?0:1;
  const bd = b.ctype==='direct_competitor'?0:1;
  if (ad!==bd) return ad-bd;
  if (b.confidence!==a.confidence) return b.confidence-a.confidence;
  return a.rank-b.rank;
});

let batch_index = 0;
for (let i=0;i<eligibleList.length;i++){
  if (i<MAX){ eligibleList[i]._selected=true; batch_index++; eligibleList[i]._batch_index=batch_index; }
  else { eligibleList[i]._selected=false; eligibleList[i]._skip_reason='over_max_5_limit (eligible but exceeds 5/run; approve in a later run)'; }
}

const out = [];
for (const e of evaluated){
  const r = e.row;
  const isSel = (e._selected === true);
  const skip = isSel ? '' : (e._skip_reason || e.skip_reason);
  out.push({ json: {
    candidate_id: str(r.candidate_id),
    discovery_request_id: str(r.discovery_request_id),
    candidate_url: e.url,
    normalized_source_url: str(r.normalized_source_url),
    domain: str(r.domain),
    candidate_type: str(r.candidate_type),
    confidence_score: e.confidence,
    rank: e.rank,
    approval_status: str(r.approval_status),
    approved_by: str(r.approved_by),
    approved_at: str(r.approved_at),
    service_hint: str(r.service_hint),
    region_hint: str(r.region_hint),
    notes: str(r.notes),
    _selected: isSel,
    _eligible: e.eligible,
    _skip_reason: skip,
    run_id: run_id,
    batch_index: isSel ? e._batch_index : 0,
    target_url: isSel ? e.url : '',
    source_type: 'scraped_web',
    platform: 'website',
    source_candidate_id: str(r.candidate_id),
    parsed_at: now,
    source_note: 'approved_candidates_runner',
    force_reprocess: false
  }});
}
return out;

// One summary item per run. Aggregates the annotated rows from the selection node.
const all = $('Select, Prioritize & Annotate').all().map(i => i.json);
const selected = all.filter(r => r._selected === true);
const skipped = all.filter(r => r._selected !== true);
const run_id = (all[0] && all[0].run_id) || '';
const now = new Date().toISOString();

const selected_urls = selected.map(r => r.candidate_url);
const handoff_lines = selected_urls.map(function(u){ return "  '" + u + "',"; }).join('\n');
const set_url_list_block = 'const rawUrls = [\n' + handoff_lines + '\n];';

return [{ json: {
  workflow: '06 - Approved Candidates Runner',
  run_id: run_id,
  generated_at: now,
  total_candidates_read: all.length,
  selected_count: selected.length,
  skipped_count: skipped.length,
  max_per_run: 5,
  processing_mode: 'manual_handoff_to_workflow_04',
  selected_urls: selected_urls,
  selected: selected.map(function(r){ return { batch_index:r.batch_index, candidate_id:r.candidate_id, candidate_url:r.candidate_url, candidate_type:r.candidate_type, confidence_score:r.confidence_score, service_hint:r.service_hint, discovery_request_id:r.discovery_request_id }; }),
  skipped: skipped.map(function(r){ return { candidate_id:r.candidate_id, candidate_url:r.candidate_url, candidate_type:r.candidate_type, reason:r._skip_reason }; }),
  workflow_04_set_url_list_block: set_url_list_block,
  operator_note: (selected.length === 0)
    ? 'No approved/unique/not_in_registry candidates to process. Approve at least one direct_competitor candidate in url_candidates, then re-run.'
    : 'Copy the URLs above into Workflow 04 -> Set URL List (max 5), run Workflow 04, then enable the disabled "Mark Candidates Processed" node here (or set approval_status=processed manually) AFTER confirming monitor_queue output.'
}}];
